\set ON_ERROR_STOP on
-- Disposable PG/PostgREST-only supplement. NEVER deploy to Supabase.
-- The SQL login password is synthetic; JWT signing keys are freshly generated by the runner.
-- The database is started on a private Docker --internal network with
-- zero host-published ports; all containers are removed by the runner.
create role authenticator noinherit login password 'fs_fixture_authenticator_only_20261029';
grant anon,authenticated to authenticator;

-- Both legacy Supabase auth.uid() session GUC and the modern PostgREST
-- verified JWT claim JSON are supported. The latter comes from PostgREST's
-- signature-validated Bearer token, not a test-supplied HTTP query field.
create or replace function auth.uid() returns uuid language sql stable
set search_path='' as $fn$
select coalesce(
 nullif(current_setting('request.jwt.claim.sub',true),''),
 nullif(nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub','')
)::uuid
$fn$;

grant usage on schema public to anon,authenticated;
grant usage on schema auth to authenticated;
grant execute on function auth.uid() to authenticated;
select 'FAMILY_WEEKLY_DISPOSABLE_POSTGREST_JWT_ROLES_PASS' as result;
